const mapping = (
	sourceNutrientKey: string,
	nutrientId: number,
	nutrientName: string,
	nutrientNumber: string,
	unitName: string,
	sourceUnitName = unitName,
) => ({
	sourceKey: "open-food-facts",
	sourceNutrientKey,
	sourceNutrientName: sourceNutrientKey,
	sourceUnitName,
	priority: 10,
	nutrientId,
	nutrientName,
	nutrientNumber,
	unitName,
});

